      'IT-enter: blocked Enter shows the reason, then Enter submits',
      () async {
        await openSheet();
        // Enter on an empty value must not be a silent no-op (F3).
        harness.sendEnter();
        await harness.waitForText(
          'Type the value first',
          timeout: const Duration(seconds: 10),
